def":false,"body_hash":"a33ea5af14c010022258b80e53949e3c","anon":true,"auth":true},{"sig":"wk_touch_chart_playback_enrichment_updated_at()","proconfig":null,"prosecdef":false,"body_hash":"9b1889f56258bf9d6554213c05019c76","anon":true,"auth":true},{"sig":"wk_touch_updated_at()","proconfig":null,"prosecdef":false,"body_hash":"301a884953d37769916294bb60562e05","anon":true,"auth":true}]$snap$::jsonb;
 r record;
 p record;
 updated integer:=0;
BEGIN
 IF jsonb_array_length(expected)<>80 THEN RAISE EXCEPTION 'STOP: expected 80 routines'; END IF;
 IF has_schema_privilege('anon','public','CREATE') OR has_schema_privilege('authenticated','public','CREATE') THEN
   RAISE EXCEPTION 'STOP: public schema allows untrusted CREATE';
 END IF;
 FOR r IN SELECT * FROM jsonb_to_recordset(expected)
     AS x(sig text,proconfig jsonb,prosecdef boolean,body_hash text,anon boolean,auth boolean)
 LOOP
   SELECT p.oid,p.proconfig,p.prosecdef,p.prosrc
   INTO p FROM pg_proc p WHERE p.oid = ('public.'||r.sig)::regprocedure;
   IF NOT FOUND OR to_jsonb(p.proconfig) IS DISTINCT FROM r.proconfig
      OR p.prosecdef IS DISTINCT FROM r.prosecdef
      OR md5(p.prosrc) IS DISTINCT FROM r.body_hash
      OR has_function_privilege('anon',p.oid,'EXECUTE') IS DISTINCT FROM r.anon
      OR has_function_privilege('authenticated',p.oid,'EXECUTE') IS DISTINCT FROM r.auth
   THEN
      RAISE EXCEPTION 'STOP: drift on function %',r.sig;
   END IF;
   EXECUTE format('ALTER FUNCTION %s SET search_path = pg_catalog, public, pg_temp',('public.'||r.sig)::regprocedure);
   IF NOT EXISTS(
      SELECT 1 FROM pg_proc q WHERE q.oid=p.oid
        AND q.proconfig @> ARRAY['search_path=pg_catalog, public, pg_temp']::text[]
        AND q.prosecdef IS NOT DISTINCT FROM r.prosecdef
        AND md5(q.prosrc)=r.body_hash
        AND has_function_privilege('anon',q.oid,'EXECUTE')=r.anon
        AND has_function_privilege('authenticated',q.oid,'EXECUTE')=r.auth
   ) THEN RAISE EXCEPTION 'STOP: postcondition failed for %',r.sig; END IF;
   updated := updated+1;
 END LOOP;
 IF updated<>80 THEN RAISE EXCEPTION 'STOP: wrong altered count'; END IF;
END $wk$;
COMMIT;
